import { AsyncLocalStorage } from "node:async_hooks";
import type { AssistantMessage, AssistantMessageEvent } from "../types";

// Physical producer identity is held here, not inferred from a terminal event,
// a source marker, or a structurally similar property on an arbitrary stream.
interface AppStreamProducer {
	completion: Promise<void>;
	children: Set<Promise<void>>;
	unknown: Set<string>;
	closed: boolean;
}
const appStreamProducers = new WeakMap<object, AppStreamProducer>();
const appStreamProducerContext = new AsyncLocalStorage<AppStreamProducer>();

/** Retain raced iterator work in the actual initiating producer, not its caller. */
export function retainAppStreamTask<T>(task: PromiseLike<T>): Promise<T> {
	const promise = Promise.resolve(task);
	const owner = appStreamProducerContext.getStore();
	if (owner) {
		if (owner.closed) throw new Error("Stream producer started work after completion");
		const joined = promise.then(() => {}, () => {}).finally(() => owner.children.delete(joined));
		owner.children.add(joined);
	}
	return promise;
}

export function getAppStreamProducer(source: object): {
	completion: Promise<void>; getUnknown(): string[];
} | undefined {
	const owner = appStreamProducers.get(source);
	return owner && Object.freeze({ completion: owner.completion, getUnknown: () => [...owner.unknown] });
}

/** Reserve BEFORE invoking the body; settle only after its actual finally and children. */
export function runAppStreamProducer(stream: AssistantMessageEventStream, operation: () => Promise<void>): void {
	if (appStreamProducers.has(stream)) throw new Error("Stream producer already registered");
	const completion = Promise.withResolvers<void>();
	const owner: AppStreamProducer = { completion: completion.promise, children: new Set(), unknown: new Set(), closed: false };
	appStreamProducers.set(stream, owner);
	void (async () => {
		try { await appStreamProducerContext.run(owner, operation); }
		catch (error) { stream.fail(error); }
		finally {
			while (owner.children.size) await Promise.allSettled([...owner.children]);
			owner.closed = true;
			completion.resolve();
		}
	})();
}

/** Wrapper consumption is not the child transport's producer completion. */
export function adoptAppStreamProducer(target: object, source: object): void {
	const owner = appStreamProducers.get(target);
	if (!owner || owner.closed) throw new Error("Stream producer ownership is unavailable");
	const child = getAppStreamProducer(source);
	if (!child) { owner.unknown.add("sdk_provider_producer_unrepresented"); return; }
	const joined = child.completion.then(() => {
		for (const reason of child.getUnknown()) owner.unknown.add(reason);
	}).finally(() => owner.children.delete(joined));
	owner.children.add(joined);
}

/** Used only for concrete unaudited subfeatures, never as a substitute for retention. */
export function markAppStreamProducerUnknown(stream: object, reason: string): void {
	const owner = appStreamProducers.get(stream);
	if (!owner || owner.closed) throw new Error("Stream producer ownership is unavailable");
	owner.unknown.add(reason);
}

